    def _walk_ask(asks, qty):
        left, cost = qty, 0.0
        for p, q in asks:
            t = min(left, q)
            cost += t * p
            left -= t
            if left <= 1e-12:
                break
        return cost / (qty - left) if qty > left else asks[0][0]

    def _brk_scan(self, s, asks, now):
        """Пробой: плотность на продажу простояла BRK_AGE секунд, её съели покупки по ленте (не меньше BRK_EAT_FRAC размера), цена вышла в зону."""
        c, sym = self.c, s["name"]
        if sym not in c["TRADE_PAIRS"] or c["ENTRY_MODE"] == "bounce":
            return
        if s["pos"] or s["order"] or s["mkt"] or s.get("bo") or now < s["cool"] or now - s["t_book"] > 2:
            return
        ask0, aq = asks[0][0], {p: q for p, q in asks}
        for r in s["zact"]:
            if r["kind"] != "aclus" or r.get("fired") or now - r["t_first"] < c["BRK_AGE"]:
                continue
            if r["traded"] < c["BRK_EAT_FRAC"] * r["usdt_max"] or ask0 < r["near"]:
                continue
            if self._zone_size(r, s["snap"], aq) > 0.3 * r["usdt_max"]:
                continue
            r["fired"] = True
            stop = r["near"] * (1 - c["BRK_STOP_BPS"] / 1e4)
            risk = (ask0 - stop) / ask0 * 1e4
            if risk > c["MAX_RISK_BPS"]:
                self.log(now, sym, "brk_skip", ask0, "пробой зоны %.6g–%.6g пропущен: риск %.0f б.п." % (r["near"], r["far"], risk))
                continue
            s["bo"] = dict(t=now + c["LATENCY"], t_sig=now, near=r["near"], far=r["far"], usdt=r["usdt_max"], traded=r["traded"], stop=stop, age=now - r["t_first"])
            self.log(now, sym, "brk_signal", ask0, "пробой зоны %.6g–%.6g: %.0fk USDT, съедено %.0fk, жила %.0f с" % (r["near"], r["far"], r["usdt_max"] / 1e3, r["traded"] / 1e3, now - r["t_first"]))
            return

