    def _be_price(self, p, extra=None):
        """Цена, при продаже остатка по которой итог позиции (с учётом уже закрытых частей и всех комиссий) равен нулю."""
        f, e = self.c["FEE"], p["entry"]
        parts = list(p["parts"]) + ([list(extra)] if extra else [])
        rem = p["qty0"] - sum(x[0] for x in parts)
        if rem <= p["qty0"] * 1e-9:
            return None
        realized = sum(x[0] * (x[1] - e) for x in parts)
        fee_paid = f * (e * p["qty0"] + sum(x[0] * x[1] for x in parts))
        return (rem * e + fee_paid - realized) / (rem * (1 - f))

